<?php
/** New independently witnessed start-side-effect envelope; no provider or financial operation. */
require __DIR__.'/task_timer_transitions.php';
$startEnvelope=$GLOBALS['essentialChecks'];$records=[];
foreach(['project'=>$ts,'standalone'=>$singlePriority]as$kind=>$writer){
 $cases=$kind==='project'?['priority','follower','extra_active','extra_closed','foreign_active']:['priority','extra_active','extra_closed','foreign_active'];
 foreach($cases as$fault){if(isset($argv[1])&&$argv[1]!==$kind.':'.$fault)continue;$owner=$b;$id=$makeTimerTask($writer,$kind,$owner,'envelope-'.$fault);$request=$key('timer-envelope-'.$kind.'-'.$fault);$table=$kind==='project'?'company_task_timers':'company_standalone_timers';$priority=$kind==='project'?'company_task_priorities':'company_standalone_priorities';$event=$kind==='project'?'company_task_start':'company_standalone_task_start';
  if($fault==='foreign_active'){$otherKind=$kind==='project'?'standalone':'project';$otherWriter=$kind==='project'?$singlePriority:$ts;$other=$makeTimerTask($otherWriter,$otherKind,$a,'foreign-envelope-'.$kind);$otherTable=$kind==='project'?'company_standalone_timers':'company_task_timers';}
  $before=timerTransitionState($db,$p);$timing=in_array($fault,['priority','follower'],true)?'early':'last_audit';$mutation=match($fault){'priority'=>"UPDATE {$p}$priority SET priority=CASE WHEN priority=4 THEN 3 ELSE 4 END WHERE issuer_id=$owner AND task_id=$id",'follower'=>"INSERT INTO {$p}company_task_followers(issuer_id,task_id,staff_id) VALUES($owner,$id,12)",'extra_active'=>"INSERT INTO {$p}$table(issuer_id,task_id,actor_id,started_at,stopped_at,seconds) VALUES($owner,$id,7,SYSDATE(),NULL,0)",'extra_closed'=>"INSERT INTO {$p}$table(issuer_id,task_id,actor_id,started_at,stopped_at,seconds) VALUES($owner,$id,7,SYSDATE(),SYSDATE(),0)",'foreign_active'=>"INSERT INTO {$p}$otherTable(issuer_id,task_id,actor_id,started_at,stopped_at,seconds) VALUES($a,$other,7,SYSDATE(),NULL,0)"};
  $witness=$p.'timer_envelope_hit';$trigger=$p.'timer_envelope_fault';$db->query('CREATE TABLE '.$witness.'(hit INT NOT NULL) ENGINE=MyISAM');$target=$timing==='early'?$table:'issuers_audit';$condition=$timing==='early'?"NEW.task_id=$id AND NEW.issuer_id=$owner":"NEW.event='$event' AND NEW.subject_id=$id AND NEW.issuer_id=$owner";$db->query("CREATE TRIGGER $trigger AFTER INSERT ON $p$target FOR EACH ROW BEGIN IF $condition THEN INSERT INTO $witness(hit) VALUES(1); $mutation; END IF; END");$caught=null;
  try{$writer->activity($owner,7,$id,1,'start',$request);}catch(Throwable$e){$caught=$e->getMessage();}finally{$db->query('DROP TRIGGER '.$trigger);}
  essentialCheck((int)$db->query('SELECT COUNT(*) n FROM '.$witness)->row()->n===1,'actual '.$kind.'/'.$fault.' '.$timing.' trigger reached');$db->query('DROP TABLE '.$witness);$record=['kind'=>$kind,'fault'=>$fault,'phase'=>$timing,'caught'=>$caught,'rollback'=>timerTransitionState($db,$p)===$before];$records[]=$record;echo 'Timer envelope observed '.json_encode($record).PHP_EOL;
  essentialCheck(in_array($caught,['issuer_task_timer_unconfirmed','issuer_task_priority_unconfirmed','issuer_project_write_unconfirmed'],true),'unrequested '.$kind.'/'.$fault.' side effect must be rejected, not adopted');essentialCheck($record['rollback'],'entire timer/task/priority/follower/grants/receipt/audit/source history rolls back '.$fault);$writer->activity($owner,7,$id,1,'start',$request);$r=$writer->get($owner,7,$id);essentialCheck($r['status']==='in_progress'&&count($r['timers'])===1,'same failed key retries one clean start after '.$fault);$writer->activity($owner,7,$id,2,'stop',$key('timer-envelope-stop-'.$kind.'-'.$fault));$db->queries=[];
 }
}
